package edu.unimagdalena.RCMU.domine.entity;import jakarta.persistence.*;import lombok.*;@Entity@Table(name = "appointment_types")@Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builderpublic class AppointmentType {    @Id    @GeneratedValue(strategy = GenerationType.IDENTITY)    private Long id;    @Column(nullable = false)    private String name;    @Column(nullable = false)    private Integer durationInMinutes;}